import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';
test('actual pinned browser focuses asynchronously loaded route headings while preserving deliberate focus and abandoning old routes',{timeout:35000},async()=>{
  const server=await testServer();let child;
  try{
    const request=server.agent();await request('POST','/auth/signup',{name:'Focus Owner',email:'focus-owner@example.test',password:'correct focus password'});
    const org=(await request('POST','/orgs',{name:'Focus organization'})).data.organization;
    const project=(await request('POST','/orgs/'+org.id+'/projects',{key:'FOCUS',name:'Focus project'})).data.project;
    const issue=(await request('POST','/projects/'+project.id+'/issues',{title:'Async route focus'})).data.issue;
    const result=await new Promise((resolve,reject)=>{
      child=spawn('/usr/bin/python3',[fileURLToPath(new URL('./focus-browser.py',import.meta.url)),JSON.stringify({url:server.url,issueId:issue.id})],{detached:true});
      let stdout='',stderr='';const timer=setTimeout(()=>{try{process.kill(-child.pid,'SIGKILL');}catch{}reject(new Error('Focus browser exceeded bounded deadline'));},30000);
      child.stdout.on('data',value=>stdout+=value);child.stderr.on('data',value=>stderr+=value);
      child.on('error',error=>{clearTimeout(timer);reject(error);});child.on('close',code=>{clearTimeout(timer);resolve({code,stdout,stderr});});
    });
    assert.equal(result.code,0,result.stderr);const proof=JSON.parse(result.stdout.trim());
    for(const name of ['delayedHeading','deliberateFocus','abandonedRoute'])assert.equal(proof[name],true,name);
  }finally{if(child?.pid){try{process.kill(-child.pid,'SIGKILL');}catch{}}await server.close();}
});
